import { field, select, checkbox, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${select({ id: "cpInput", label: "Input value type", options: [{label:"Scroll position",value:"scroll"},{label:"Viewport width (100vw)",value:"vw"},{label:"Viewport height (100vh)",value:"vh"},{label:"Container query width (cqw)",value:"cqw"},{label:"Custom value",value:"custom"}], value: "scroll" })}${field({ id: "cpCustomInput", label: "Custom input value", value: "var(--scroll-pos)", attrs: 'id="cpCustomInput"' })}</div><div class="field-grid">${field({ id: "cpFrom", label: "Start (from)", type: "number", value: "0" })}${field({ id: "cpTo", label: "End (to)", type: "number", value: "500" })}</div><div class="field-grid">${field({ id: "cpOutputStart", label: "Output range start", type: "number", value: "0" })}${field({ id: "cpOutputEnd", label: "Output range end", type: "number", value: "1" })}</div><div class="field-grid">${field({ id: "cpProperty", label: "CSS property", value: "opacity" })}${field({ id: "cpSelector", label: "Selector", value: ".fade-on-scroll" })}</div>`,generate(root) {const inputType = root.querySelector("#cpInput").value;const customInput = root.querySelector("#cpCustomInput").value.trim() || "var(--scroll-pos)";const from = parseFloat(root.querySelector("#cpFrom").value) || 0;const to = parseFloat(root.querySelector("#cpTo").value) || 500;const outStart = parseFloat(root.querySelector("#cpOutputStart").value) || 0;const outEnd = parseFloat(root.querySelector("#cpOutputEnd").value) || 1;const property = root.querySelector("#cpProperty").value.trim() || "opacity";const selector = root.querySelector("#cpSelector").value.trim() || ".fade-on-scroll";const inputMap = {scroll: "scroll-position",vw: "100vw",vh: "100vh",cqw: "100cqw",custom: customInput};const inputVal = inputMap[inputType] || customInput;const progressExpr = `progress(${inputVal} from ${from} to ${to})`;const outRange = outEnd - outStart;const mappedExpr = outStart === 0 && outEnd === 1? progressExpr: `calc(${outStart} + ${progressExpr} * ${outRange})`;const lines = [];lines.push("/* CSS progress() function — Chrome 138+ */");lines.push("/* Maps an input value from one range to a 0-1 progress value. */");lines.push("");lines.push(`${selector} {`);lines.push(` ${property}: ${mappedExpr};`);lines.push(`}`);lines.push("");lines.push("/* How it works: */");lines.push(`/* progress(${inputVal} from ${from} to ${to}) returns: */`);lines.push(`/* - 0 when ${inputVal} <= ${from} */`);lines.push(`/* - 1 when ${inputVal} >= ${to} */`);lines.push(`/* - A value between 0-1 when ${inputVal} is between ${from} and ${to} */`);if (outStart !== 0 || outEnd !== 1) {lines.push(`/* Output mapped to [${outStart}, ${outEnd}]: ${mappedExpr} */`);}lines.push("");lines.push("/* Browser support: Chrome 138+, Edge 138+. Firefox and Safari in development. */");lines.push("/* progress() works in any CSS property — opacity, transform, width, color-mix, etc. */");lines.push("");lines.push("/* Common patterns: */");lines.push("/* Fade in: opacity: progress(scroll-position from 0 to 300); */");lines.push("/* Scale up: scale: calc(0.8 + progress(scroll-position from 0 to 400) * 0.2); */");lines.push("/* Color shift: color: color-mix(in oklab, red, blue calc(progress(100vw from 320 to 1200) * 100%)); */");const pct = Math.min(100, Math.max(0, ((300 - from) / (to - from)) * 100));const preview = `<div style="border:1px solid #e5e7eb;border-radius:10px;padding:16px;background:#f9fafb"><div style="font-size:12px;font-weight:600;margin-bottom:10px;color:#374151">progress(${inputVal} from ${from} to ${to})</div><div style="position:relative;height:40px;background:#e5e7eb;border-radius:20px;overflow:hidden;margin-bottom:12px"><div style="position:absolute;left:0;top:0;height:100%;width:${pct}%;background:linear-gradient(90deg,#3b82f6,#8b5cf6);border-radius:20px;transition:width 0.3s"></div><div style="position:absolute;left:0;top:0;width:100%;height:100%;display:flex;align-items:center;justify-content:space-between;padding:0 16px;font-size:11px;color:#fff;mix-blend-mode:difference"><span>${from}</span><span>~${Math.round(from + (to - from) * pct / 100)}</span><span>${to}</span></div></div><div style="display:flex;gap:16px;flex-wrap:wrap;font-size:12px"><div style="flex:1;min-width:100px;background:#fff;border:1px solid #e5e7eb;border-radius:6px;padding:10px;text-align:center"><div style="color:#6b7280;margin-bottom:4px">Progress value</div><div style="font-weight:700;font-family:monospace">${(pct / 100).toFixed(3)}</div></div><div style="flex:1;min-width:100px;background:#fff;border:1px solid #e5e7eb;border-radius:6px;padding:10px;text-align:center"><div style="color:#6b7280;margin-bottom:4px">Mapped output</div><div style="font-weight:700;font-family:monospace">${property}: ${(outStart + (pct / 100) * outRange).toFixed(3)}</div></div><div style="flex:1;min-width:100px;background:#fff;border:1px solid #e5e7eb;border-radius:6px;padding:10px;text-align:center"><div style="color:#6b7280;margin-bottom:4px">Input range</div><div style="font-weight:700;font-family:monospace">${from} → ${to}</div></div></div><p style="margin:8px 0 0;font-size:11px;color:#6b7280">The progress bar shows a simulated mid-range value. The actual progress value changes as the input (scroll position, viewport width, etc.) moves between ${from} and ${to}.</p></div>`;return { output: lines.join("\n"), preview };}};